// Прямые запросы к Supabase — только GET и RPC-функции чтения; ничего не пишут.
import { expect, Locator, Page } from '@playwright/test';

export const TEST_COMPANY_ID = '4432bd2f-3f47-43cf-8ef2-b0c16436f025';
export const DISPATCHER_EMAIL = 'gesaday533@bwingmedia.com';

/** Купонные и тарифные события — их видит только супер-админ (Admin Panel → Audit log). */
export const ADMIN_ONLY_EVENTS =
  /Coupon (created|changed|disabled|attached to an account|detached from its account)|Plan (granted|changed|revoked)/;

export type SupabaseSession = { base: string; apikey: string; token: string };

/**
 * Открыть /dashboard и собрать данные для прямого запроса от имени текущей сессии:
 * - адрес Supabase и apikey — из первого запроса страницы к {ref}.supabase.co (supabase-js шлёт apikey в каждом запросе);
 * - access_token — из localStorage страницы (`sb-<ref>-auth-token`).
 * Паролей нет: используется только сохранённая сессия.
 */
export async function supabaseSession(page: Page): Promise<SupabaseSession> {
  const reqPromise = page.waitForRequest(
    (r) => /^https:\/\/[a-z0-9]+\.supabase\.co\/(rest|auth|functions)\/v1\//.test(r.url()) && !!r.headers()['apikey'],
    { timeout: 30_000 },
  );
  await page.goto('/dashboard');
  const req = await reqPromise;
  const apikey = req.headers()['apikey'];
  const base = new URL(req.url()).origin;
  const ref = new URL(base).hostname.split('.')[0];

  const token = await page.evaluate((key) => {
    const raw = window.localStorage.getItem(key);
    if (!raw) return null;
    try {
      const parsed = JSON.parse(raw);
      return (parsed?.access_token ?? parsed?.currentSession?.access_token ?? null) as string | null;
    } catch {
      return null;
    }
  }, `sb-${ref}-auth-token`);

  expect(apikey, 'apikey из запроса страницы к Supabase').toBeTruthy();
  expect(token, `access_token в localStorage «sb-${ref}-auth-token» (сессия жива?)`).toBeTruthy();
  return { base, apikey, token: token as string };
}

function headers(s: SupabaseSession) {
  return { apikey: s.apikey, Authorization: `Bearer ${s.token}`, Accept: 'application/json' };
}

/** GET /rest/v1/AuditLog?select=* от имени сессии. Возвращает статус и тело. */
export async function readAuditLog(page: Page, s: SupabaseSession) {
  const res = await page.request.get(`${s.base}/rest/v1/AuditLog?select=*`, { headers: headers(s) });
  return { status: res.status(), body: await res.json().catch(async () => res.text()) };
}

/** RPC team_change_history (функция только читает) для указанной компании. */
export async function teamChangeHistory(page: Page, s: SupabaseSession, companyId: string) {
  const res = await page.request.post(`${s.base}/rest/v1/rpc/team_change_history`, {
    headers: { ...headers(s), 'Content-Type': 'application/json' },
    data: { p_company_id: companyId },
  });
  return { status: res.status(), body: await res.json().catch(async () => res.text()) };
}

/** /Team → блок «Change history» загружен (заголовок виден). */
export async function openTeamChangeHistory(page: Page): Promise<Locator> {
  await page.goto('/Team');
  const heading = page.getByText('Change history', { exact: true });
  await expect(heading).toBeVisible({ timeout: 30_000 });
  await heading.scrollIntoViewIfNeeded();
  return heading;
}

/** Admin Panel → вкладка «Audit log». */
export async function openAuditLogTab(page: Page) {
  await page.goto('/adminpanel');
  await page.getByRole('tab', { name: 'Audit log', exact: true })
    .or(page.getByRole('button', { name: 'Audit log', exact: true }))
    .first()
    .click();
  await expect(page.getByRole('heading', { name: 'Audit log', exact: true })
    .or(page.getByText('Audit log', { exact: true })).first()).toBeVisible();
}

/**
 * Строки журнала: строка таблицы с исполнителем (email) в колонке Who. Заголовок и раскрытые детали email-а исполнителя не содержат…
 * кроме деталей с полем Account — поэтому строки считаем ДО раскрытия.
 * // не сверено с сайтом: строка — tr или role=row (на скрине таблица со стрелкой-раскрытием).
 */
export function auditRows(page: Page): Locator {
  return page.locator('tr, [role="row"]').filter({ hasText: /@[a-z0-9.-]+\.[a-z]{2,}/i });
}

/**
 * Фильтр по типу (по умолчанию «Everything») → выбрать значение.
 * // не сверено с сайтом: нативный <select> или кастомный combobox — поддержаны оба.
 */
export async function chooseAuditFilter(page: Page, option: string) {
  const control = page.getByRole('combobox').first();
  await expect(control).toBeVisible();
  const tag = await control.evaluate((el) => el.tagName.toLowerCase());
  if (tag === 'select') {
    await control.selectOption({ label: option });
    await expect.poll(() => control.evaluate((el) => (el as HTMLSelectElement).selectedOptions[0]?.text.trim()))
      .toBe(option);
  } else {
    await control.click();
    await page.getByRole('option', { name: option, exact: true }).click();
    await expect(control).toContainText(option);
  }
}
